#pragma once#include <vector>#include <map>#include <algorithm>template<typename T>void Swap( T &mb ){  BYTE *pB = (BYTE*)&mb;  for (size_t i = 0; i < sizeof(T) / 2; ++i)    std::swap(pB[i], pB[sizeof(T) - i - 1]);}class KModbusTcpHandle{protected:#pragma pack( push )#pragma pack( 1 )  struct SMBAheaderRaw  {    SMBAheaderRaw()    {      ZeroMemory( this, sizeof(*this) );    }    WORD transactionID;    WORD protocolID;    WORD length;    BYTE UnitID;  };  struct SAddrCount  {    WORD addr;    WORD vc;  };#pragma pack( pop )  typedef std::vector<BYTE> tPduCont_;  struct SInData  {    SInData() : allInBytes(0), allOutBites(0)    {      Reset();    };    void Reset()    {      nHeaderRcv = nPduRcv = nLimitPdu = 0;      memset( &header, -1, sizeof(header) );    }    SMBAheaderRaw header;    int nHeaderRcv;    int nPduRcv;    int nLimitPdu;    size_t allInBytes, allOutBites;    tPduCont_ pduBuffer;    tPduCont_ outBuffer;  };  typedef std::map<SOCKET, SInData> tSocksDataCont_;  tSocksDataCont_ m_InDatas;public:  KModbusTcpHandle();  void OnRead( SOCKET &sockIn );private:  int Get( SOCKET &sockIn, char* pIn, int &recved, int limit );  int SEND( SOCKET &sockIn, SInData &inData, LPCSTR buf, int len,int flags );private:  void ReadCoilStatus_01( SOCKET &sockIn, BYTE functionCode, SInData &inData, BYTE *pData, int dataLen );//Чтение DO Дискретное                     20001 - 29999  void ReadInputStatus_02( SOCKET &sockIn, BYTE functionCode, SInData &inData, BYTE *pData, int dataLen );//Чтение DI Дискретное                    10001 - 19999  void ReadHoldingRegisters_03( SOCKET &sockIn, BYTE functionCode, SInData &inData, BYTE *pData, int dataLen );//Чтение AO 16 битное                40001 - 49999  void ReadInputRegisters_04( SOCKET &sockIn, BYTE functionCode, SInData &inData, BYTE *pData, int dataLen );//Чтение AI 16 битное                  30001 - 39999  void ForceSingleCoil_05( SOCKET &sockIn, BYTE functionCode, SInData &inData, BYTE *pData, int dataLen );//Запись одного DO Дискретное             20001 - 29999  void PresetSingleRegister_06( SOCKET &sockIn, BYTE functionCode, SInData &inData, BYTE *pData, int dataLen );//Запись одного AO 16 битное         40001 - 49999  void ForceMultipleCoils_15( SOCKET &sockIn, BYTE functionCode, SInData &inData, BYTE *pData, int dataLen );//Запись нескольких DO Дискретное      20001 - 29999  void PresetMultipleRegisters_16( SOCKET &sockIn, BYTE functionCode, SInData &inData, BYTE *pData, int dataLen );//Запись нескольких AO 16 битное  40001 - 49999protected:  virtual bool OnCoilStatus_01_Read( WORD addr, WORD count, BYTE (&outBits)[260] ) = 0;  virtual bool OnInputStatus_02_Read( WORD addr, WORD count, BYTE (&outBits)[260] ) = 0;  virtual bool OnHoldingRegisters_03_Read( WORD addr, WORD count, BYTE (&outBytes)[260] ) = 0;  virtual bool OnInputRegisters_04_Read( WORD addr, WORD count, BYTE (&outBytes)[260] ) = 0;  virtual bool OnSingleCoil_05_Write( WORD addr, BYTE *pMbRaw, WORD len ) = 0;  virtual bool OnSingleRegister_06_Write( WORD addr, BYTE *pMbRaw, WORD len ) = 0;  virtual bool OnMultipleCoils_15_Write( WORD addr, WORD countRegs, BYTE nextBytesC, BYTE *pBits ) = 0;  virtual bool OnMultipleRegisters_16_Write( WORD addr, WORD countRegs, BYTE nextBytesC, BYTE *pBytes ) = 0;};